begin;
create extension if not exists pgcrypto;
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 100), treasury_address text not null, max_payment text not null default '100000', created_at timestamptz not null default now());
create table public.memberships (organization_id uuid references public.organizations on delete cascade, user_id uuid references auth.users on delete cascade, role text not null check(role in ('owner','admin','approver','viewer')), primary key(organization_id,user_id), unique(user_id));
create table public.contractors (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,name text not null,email text not null,department text not null default '',wallet text not null,rate text not null,status text not null default 'active' check(status in ('active','inactive')),created_at timestamptz not null default now(),unique(organization_id,email),unique(organization_id,wallet),unique(organization_id,id));
create table public.sources (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,name text not null,storage_path text,source_hash text not null,content jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(organization_id,id));
create table public.payroll_runs (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,name text not null,period text not null,status text not null default 'DRAFT' check(status in ('DRAFT','PROCESSING','ACTION_REQUIRED','PREPARED','READY','APPROVED','SUBMITTED','PAID','FAILED')),source_id uuid,rows jsonb not null default '[]',findings jsonb not null default '[]',plan jsonb,summary text,digest text unique,error text,demo boolean not null default false,created_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,source_id) references public.sources(organization_id,id));
create table public.ai_operations (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,run_id uuid not null,operation text not null,input_hash text not null,output_hash text,prompt_version text not null,model text not null,status text not null check(status in ('PENDING','RUNNING','COMPLETED','FAILED','RETRYING','SKIPPED')),retry_count integer not null default 0,result jsonb,error text,started_at timestamptz,completed_at timestamptz,lease_until timestamptz,created_at timestamptz not null default now(),unique(run_id,operation,input_hash,prompt_version),foreign key(organization_id,run_id) references public.payroll_runs(organization_id,id));
create table public.approvals (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,run_id uuid not null,plan_hash text not null,user_id uuid not null references auth.users,wallet text not null,transaction_bytes text not null,transaction_digest text not null,expires_at timestamptz not null,created_at timestamptz not null default now(),unique(run_id,plan_hash),foreign key(organization_id,run_id) references public.payroll_runs(organization_id,id));
create table public.transactions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,run_id uuid not null unique,digest text not null unique,plan_hash text not null,status text not null check(status in ('SUBMITTED','CONFIRMED','FAILED')),effects jsonb,reconciled_at timestamptz,created_at timestamptz not null default now(),foreign key(organization_id,run_id) references public.payroll_runs(organization_id,id));
create table public.paid_invoices (organization_id uuid not null,contractor_id uuid not null,invoice_id text not null,run_id uuid not null,primary key(organization_id,contractor_id,invoice_id),foreign key(organization_id,contractor_id) references public.contractors(organization_id,id),foreign key(organization_id,run_id) references public.payroll_runs(organization_id,id));
create table public.audit_logs (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,user_id uuid references auth.users,run_id uuid,action text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now(),foreign key(organization_id,run_id) references public.payroll_runs(organization_id,id));
create index on public.payroll_runs(organization_id,created_at desc);
create index on public.ai_operations(run_id);
create index on public.audit_logs(organization_id,created_at desc);
create function public.member_of(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships where organization_id=org and user_id=auth.uid()) $$;
revoke all on function public.member_of(uuid) from public;grant execute on function public.member_of(uuid) to authenticated;
alter table public.organizations enable row level security;
alter table public.memberships enable row level security;
create policy member_read on public.organizations for select to authenticated using(public.member_of(id));
create policy member_read on public.memberships for select to authenticated using(public.member_of(organization_id));
do $$ declare t text; begin foreach t in array array['contractors','sources','payroll_runs','ai_operations','approvals','transactions','paid_invoices','audit_logs'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy member_read on public.%I for select to authenticated using(public.member_of(organization_id))',t);end loop;end $$;
-- Writes use authenticated, role-checked server routes. The public key cannot mutate financial state.
revoke all on all tables in schema public from anon;
revoke insert,update,delete on all tables in schema public from authenticated;
grant select on all tables in schema public to authenticated;
grant all on all tables in schema public to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('payroll-sources','payroll-sources',false,2000000,array['text/csv','application/json','text/plain','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do nothing;
create policy source_read on storage.objects for select to authenticated using(bucket_id='payroll-sources' and exists(select 1 from public.memberships m where m.organization_id::text=(storage.foldername(name))[1] and m.user_id=auth.uid()));
create function public.create_workspace(p_user uuid,p_name text,p_treasury text) returns uuid language plpgsql security definer set search_path='' as $$ declare result uuid; begin if exists(select 1 from public.memberships where user_id=p_user) then raise exception 'Workspace already exists';end if;insert into public.organizations(name,treasury_address) values(p_name,p_treasury) returning id into result;insert into public.memberships values(result,p_user,'owner');return result;end $$;
revoke all on function public.create_workspace(uuid,text,text) from public,anon,authenticated;grant execute on function public.create_workspace(uuid,text,text) to service_role;
create function public.reconcile_payroll(p_org uuid,p_run uuid,p_digest text,p_hash text,p_effects jsonb) returns void language plpgsql security definer set search_path='' as $$ declare r public.payroll_runs; p jsonb; i text; begin select * into r from public.payroll_runs where id=p_run and organization_id=p_org for update;if r.status='PAID' and r.digest=p_digest then return;end if;if r.status not in ('APPROVED','SUBMITTED') or r.plan->>'hash'<>p_hash then raise exception 'Invalid reconciliation state';end if;for p in select * from jsonb_array_elements(r.plan->'payments') loop for i in select jsonb_array_elements_text(p->'invoiceIds') loop insert into public.paid_invoices values(p_org,(p->>'contractorId')::uuid,lower(trim(i)),p_run);end loop;end loop;insert into public.transactions(organization_id,run_id,digest,plan_hash,status,effects,reconciled_at) values(p_org,p_run,p_digest,p_hash,'CONFIRMED',p_effects,now()) on conflict(run_id) do update set status='CONFIRMED',effects=excluded.effects,reconciled_at=now();update public.payroll_runs set status='PAID',digest=p_digest,error=null where id=p_run;insert into public.audit_logs(organization_id,run_id,action,metadata) values(p_org,p_run,'Payment reconciled',jsonb_build_object('digest',p_digest));end $$;
revoke all on function public.reconcile_payroll(uuid,uuid,text,text,jsonb) from public,anon,authenticated;grant execute on function public.reconcile_payroll(uuid,uuid,text,text,jsonb) to service_role;
commit;
